import {ID,SCENES} from './core.js';import {createController} from './controller.js';import {installPanel} from './panel.js';import css from './styles.css';
export const name='pwnvader-wallpapers-client',inject=['theme','slots'];
export function apply(ctx){let controller;ctx.effect(()=>{const style=document.createElement('style');style.dataset.plugin=ID;style.textContent=css;document.head.append(style);controller=createController(ctx.theme);return()=>{controller.dispose();style.remove();};});ctx.on('theme/change',()=>controller.onThemeChange());
 ctx.provide('pwnvaderWallpapers',{version:1,getSettings:()=>controller.state,applySettings:v=>controller.update(v),subscribe:f=>controller.subscribe(f)});
 installPanel(ctx,{id:ID,title:'Wallpapers',position:138,controller,fields:[{key:'scene',label:'Escena',options:SCENES.map(v=>[v,v])},{key:'brightness',label:'Brillo',min:.2,max:1.5,step:.05},{key:'scrim',label:'Oscurecer',min:0,max:.85,step:.05},{key:'speed',label:'Velocidad',min:.1,max:2,step:.1},{key:'fps',label:'FPS',min:5,max:30,step:1},{key:'fit',label:'Ajuste',options:[['cover','Cubrir'],['contain','Completo']]},{key:'power',label:'Energía',options:[['saver','Ahorro'],['smooth','Fluido']]},{key:'shuffle',label:'Rotación',options:[['off','Desactivada'],['startup','Al iniciar'],['hourly','Cada hora']]},{key:'paused',label:'Pausar',type:'checkbox'},{key:'media',label:'Archivo local',type:'file',accept:'image/png,image/jpeg,image/webp,image/avif,video/mp4,video/webm',run:f=>controller.importMedia(f)}],actions:[['Siguiente',()=>controller.next()],['Eliminar archivo',()=>controller.clear()],['Restablecer',()=>controller.reset()]]});
}
