export const ID='dsh-pwnvader-wallpapers',KEY=ID+':v1';
export const SCENES=['none','aurora','ocean','space','ascii-aurora','ascii-aurora-fjord','ascii-earthrise','ascii-matrix-rain','ascii-night-coast','ascii-starfield','local'];
export const DEFAULTS=Object.freeze({version:1,scene:'aurora',brightness:1,scrim:.3,speed:1,fps:20,fit:'cover',paused:false,power:'saver',shuffle:'off'});
const number=(v,d,min,max)=>typeof v==='number'&&Number.isFinite(v)?Math.max(min,Math.min(max,v)):d;
export function normalize(v){v=v&&typeof v==='object'?v:{};return {version:1,scene:SCENES.includes(v.scene)?v.scene:DEFAULTS.scene,brightness:number(v.brightness,1,.2,1.5),scrim:number(v.scrim,.3,0,.85),speed:number(v.speed,1,.1,2),fps:Math.round(number(v.fps,20,5,30)),fit:v.fit==='contain'?'contain':'cover',paused:v.paused===true,power:v.power==='smooth'?'smooth':'saver',shuffle:['off','startup','hourly'].includes(v.shuffle)?v.shuffle:'off'};}
export function nextScene(current,random=Math.random){const choices=SCENES.filter(s=>!['none','local',current].includes(s));return choices[Math.min(choices.length-1,Math.max(0,Math.floor(random()*choices.length)))];}
export function frameRate(s,{hidden=false,reduced=false,idle=0}={}){return s.paused||hidden||reduced||s.scene==='none'?0:s.power==='saver'&&idle>30000?Math.min(5,s.fps):s.fps;}
export function validateMedia(file){const types=['image/png','image/jpeg','image/webp','image/avif','video/mp4','video/webm'];if(!types.includes(file.type))throw Error('Usa PNG, JPEG, WebP, AVIF, MP4 o WebM.');const limit=file.type.startsWith('video/')?200*1024**2:64*1024**2;if(file.size>limit)throw Error('El archivo supera el límite: imágenes 64 MiB, videos 200 MiB.');return file.type.startsWith('video/')?'video':'image';}
export function fitRect(width,height,sourceWidth,sourceHeight,fit='cover'){const ratio=(fit==='contain'?Math.min:Math.max)(width/sourceWidth,height/sourceHeight);return {x:(width-sourceWidth*ratio)/2,y:(height-sourceHeight*ratio)/2,width:sourceWidth*ratio,height:sourceHeight*ratio};}
